export function isSupportedRegionalPricingCountry(
  countryCode: unknown,
): countryCode is keyof typeof REGIONAL_PRICING_COUNTRY_TO_MARKET {
  return (
    typeof countryCode === "string" &&
    countryCode.trim().toUpperCase() in REGIONAL_PRICING_COUNTRY_TO_MARKET
  );
}

export function getRegionalPricingMarket(
  countryCode?: string | null,
): RegionalPricingMarket {
  const normalizedCountry = countryCode?.trim().toUpperCase() ?? "";
  const marketId =
    REGIONAL_PRICING_COUNTRY_TO_MARKET[
      normalizedCountry as keyof typeof REGIONAL_PRICING_COUNTRY_TO_MARKET
    ] ?? DEFAULT_REGIONAL_PRICING_MARKET_ID;
  return REGIONAL_PRICING_MARKETS[marketId];
}

export function getRegionalStripePriceLookupKey(
  planTarget: string,
  catalogVersion: number = REGIONAL_PRICING_CATALOG_VERSION,
): string {
  return `moneko_${planTarget}_v${catalogVersion}`;
}

export function isSupportedRegionalCurrency(
  currencyCode: unknown,
): currencyCode is (typeof REGIONAL_PRICING_CURRENCIES)[number] {
  return (
    typeof currencyCode === "string" &&
    (REGIONAL_PRICING_CURRENCIES as readonly string[]).includes(
      currencyCode.trim().toUpperCase(),
    )
  );
}

